// Settled cohort orders have their own reveal. They are never queued Luckboxes
// and must not inherit a Luckbox index, BoxSpin, or a transaction to open them.
import { CHAIN, CONTRACTS } from './chain-config.js';
import { getActingAddress, get, subscribe } from './store.js';
import { readDegenesisOrders, isDegenesisActive } from './degenesis.js';
import { publishPendingActions, clearPendingActions } from './pending-actions.js';
import { registerComponentPoll } from './component-poll.js';
import { queueReveal, DEGENESIS_REVEAL_COMPLETE_EVENT, RESULT_REVEAL_ABORT_EVENT } from '../components/reveal-queue.js';

const SOURCE = 'degenesis-results';
const PREFIX = `degenerus:degenesis-results:v1:${CHAIN.id}:${CONTRACTS.GAME?.toLowerCase() ?? 'pending'}`;
export function degenesisResultSequence(order, player) {
  const day = Number(order?.degenesisDay), index = Number(order?.orderIndex);
  if (!order?.resolved || !Number.isInteger(day) || day < 1 || day > 7
    || !Number.isInteger(index) || index < 0 || !/^0x[\da-f]{40}$/i.test(player || '')) return null;
  const address = player.toLowerCase();
  return { kind: 'degenesis', degenesisDay: day,
    presentationId: `${PREFIX}:${address}:${day}:${index}`,
    revealRelease: { address }, result: order.resolved };
}

export function mountDegenesisResults({
  readOrders = readDegenesisOrders, enqueue = queueReveal,
  getPlayer = () => get('ui.mode') === 'combined' ? null : getActingAddress(),
  events = document, storage,
  poll = registerComponentPoll, watch = subscribe,
} = {}) {
  if (storage === undefined) {
    try { storage = globalThis.localStorage; } catch (_) { storage = null; }
  }
  let player = null, rows = [], generation = 0, stopped = false, settled = false;
  const queued = new Set();
  const consumed = new Set();
  const key = address => `${PREFIX}:${address}`;
  const save = () => {
    try { storage?.setItem(key(player), JSON.stringify([...consumed])); } catch (_) { /* private mode */ }
  };
  const publish = () => publishPendingActions(SOURCE, rows.flatMap(order => {
    const owner = player;
    const seq = degenesisResultSequence(order, player);
    if (!seq || consumed.has(seq.presentationId) || queued.has(seq.presentationId)) return [];
    return [{ id: seq.presentationId, kind: 'degenesis', state: 'ready',
      label: `Degenesis · Day ${seq.degenesisDay}`, detail: 'Open your settled box',
      dismissScope: player, order: 30,
      run: () => {
        if (stopped || player !== owner || String(getPlayer() || '').toLowerCase() !== owner
          || consumed.has(seq.presentationId) || queued.has(seq.presentationId)) return false;
        if (enqueue(seq) === false) return false;
        queued.add(seq.presentationId);
        publish();
        return true;
      },
    }];
  }));
  const refresh = async () => {
    const address = String(getPlayer() || '').toLowerCase();
    if (address !== player) {
      player = address; rows = []; settled = false; consumed.clear();
      try { for (const id of JSON.parse(storage?.getItem(key(player)) || '[]')) consumed.add(String(id)); }
      catch (_) { /* bad cache */ }
      publish();
    }
    const request = ++generation;
    if (!address || stopped || (settled && !isDegenesisActive())) return;
    let orders;
    try { orders = await readOrders(address); } catch (_) { return; }
    if (stopped || request !== generation || address !== String(getPlayer() || '').toLowerCase()) return;
    rows = orders;
    settled = rows.length > 0 && rows.every(order => order.resolved != null);
    publish();
  };
  const complete = event => {
    const id = String(event.detail?.presentationId || '');
    if (!queued.delete(id)) return;
    const owner = String(event.detail?.address || player || '').toLowerCase();
    if (owner === player && id.startsWith(`${PREFIX}:${player}:`)) {
      consumed.add(id); save(); publish();
    } else if (owner && id.startsWith(`${PREFIX}:${owner}:`)) {
      try {
        const prior = new Set(JSON.parse(storage?.getItem(key(owner)) || '[]'));
        prior.add(id); storage?.setItem(key(owner), JSON.stringify([...prior]));
      } catch (_) { /* private mode */ }
    }
  };
  const abort = event => {
    for (const item of event.detail?.released || []) {
      if (item.kind === 'degenesis') queued.delete(item.presentationId);
    }
    publish();
  };
  events.addEventListener(DEGENESIS_REVEAL_COMPLETE_EVENT, complete);
  events.addEventListener(RESULT_REVEAL_ABORT_EVENT, abort);
  const unsubs = ['connected.address', 'viewing.address', 'ui.mode']
    .map(path => watch(path, () => { void refresh(); }));
  const unpoll = poll(refresh, 60_000);
  void refresh();
  return { refresh, dispose() {
    stopped = true; generation++;
    unpoll(); unsubs.forEach(fn => fn());
    events.removeEventListener(DEGENESIS_REVEAL_COMPLETE_EVENT, complete);
    events.removeEventListener(RESULT_REVEAL_ABORT_EVENT, abort);
    clearPendingActions(SOURCE);
  } };
}
